import { canonicalSha256 } from '../core/canonical-json.mjs';
function unionFind(values){const parent=new Map(values.map((v)=>[v,v]));const find=(x)=>{let p=parent.get(x);while(p!==parent.get(p))p=parent.get(p);let c=x;while(parent.get(c)!==p){const n=parent.get(c);parent.set(c,p);c=n;}return p;};const union=(a,b)=>{const ra=find(a),rb=find(b);if(ra!==rb)parent.set(rb,ra);};return{find,union};}
export function bundleWorkUnits({scope,relations=[]}){const files=(scope?.included??[]).map((item)=>item.path).sort();const set=new Set(files);const uf=unionFind(files);for(const edge of relations)if(set.has(edge.from)&&set.has(edge.to))uf.union(edge.from,edge.to);const groups=new Map();for(const file of files){const root=uf.find(file);if(!groups.has(root))groups.set(root,[]);groups.get(root).push(file);}const units=[...groups.values()].map((group)=>{group.sort();const base={files:group,relations:relations.filter((edge)=>group.includes(edge.from)&&group.includes(edge.to))};return Object.freeze({...base,unitId:`WU-${canonicalSha256(base).slice(0,16)}`});}).sort((a,b)=>a.unitId.localeCompare(b.unitId));const payload={schemaVersion:1,units};return Object.freeze({...payload,bundleSha256:canonicalSha256(payload)});}
